CREATE TABLE q(test,expr); INSERT INTO q VALUES('1','a NEAR c'),('2','a AND c'),('3','"a c"'),('4','"c a"'),('5','"a c" NEAR/1 g'),('6','"a c" NEAR/0 g'); CREATE TABLE result AS SELECT test,'ASC' AS direction,(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid ASC)) AS docs FROM q UNION ALL SELECT test,'DESC',(SELECT group_concat(docid,',') FROM (SELECT docid FROM t1 WHERE t1 MATCH q.expr ORDER BY docid DESC)) FROM q;